void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec2 ball = vec2(cos(.49*iTime)/4. + sin(.37*iTime)/3., cos(.51*iTime)/3. + sin(.72*iTime)/5.);
    ball.x += 0.5;
    ball.y += 0.5;

    float r = 0.03;

    float a = length(ball.xy);
    float theta = atan(ball.y, ball.x);

    vec2 p0 = vec2(0.,0.);
    float a1 = (a*a-r*r)/a;
    float a2 = (r*sqrt(a*a-r*r)/a);
    vec2 p1 = vec2(cos(theta) * a1 + sin(theta) * a2,
                   sin(theta) * a1 - cos(theta) * a2);
    vec2 p2 = vec2(cos(theta) * a1 - sin(theta) * a2,
                   sin(theta) * a1 + cos(theta) * a2);


    float d = sqrt(dot(ball-uv, ball-uv));


    float Ax2 = (-p1.y*p2.x + p0.y*(-p1.x + p2.x) + p0.x*(p1.y - p2.y) + p1.x*p2.y); 
    float s = (p0.y*p2.x - p0.x*p2.y + (p2.y - p0.y)*uv.x + (p0.x - p2.x)*uv.y);
    float t = (p0.x*p1.y - p0.y*p1.x + (p0.y - p1.y)*uv.x + (p1.x - p0.x)*uv.y);

    // Output to screen

    fragColor = texture(iChannel0,uv);

    if (d < r) {
        fragColor.xz += vec2(0.2, 0.6);
    } else {
        if (s > 0. && t > 0. && s + t < Ax2) {
            fragColor.z += 0.3;
        }
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec4 c = texture(iChannel0,uv);
    fragColor = c;

    vec2 ball = vec2(cos(.49*iTime)/4. + sin(.37*iTime)/3., cos(.51*iTime)/3. + sin(.72*iTime)/5.);

    ball.x += 0.5;
    ball.y += 0.5;

    float r = 0.03;

    float d = sqrt(dot(ball-uv, ball-uv));

    vec4 n = texture(iChannel0, uv + vec2(0,1)/iResolution.xy);
    vec4 w = texture(iChannel0, uv + vec2(-1,0)/iResolution.xy);
    vec4 e = texture(iChannel0, uv + vec2(1,0)/iResolution.xy);
    vec4 s = texture(iChannel0, uv + vec2(0,-1)/iResolution.xy);

    float speed = 0.2;
    float radiance = 0.001;
    fragColor.x += (n.x + w.x + e.x + s.x)*speed - fragColor.x*speed*(4.+radiance);


    if (d < r) {
        fragColor.x += 0.017;
    }




    if (iTime < 0.1) {
        fragColor = vec4(0.0,0.0,0.0,1.0);
    }
}
